/* ===== Design tokens ===== */
:root {
  --bg-page:        #0f1117;
  --bg-surface:     #1a1d27;
  --bg-input:       #12141c;
  --border-idle:    #2e3148;
  --border-focus:   #6c8cff;
  --border-error:   #f06a6a;
  --text-primary:   #e8eaf6;
  --text-secondary: #9195b0;
  --text-label:     #c4c8e8;
  --accent:         #6c8cff;
  --accent-hover:   #8fabff;
  --error:          #f06a6a;
  --success:        #5ecf8a;
  --radius:         8px;
  --transition:     180ms ease;
}

/* ===== Page ===== */
body {
  background-color: var(--bg-page);
  color: var(--text-primary);
  font-family: system-ui, -apple-system, "Segoe UI", Roboto, sans-serif;
  font-size: 1rem;
  line-height: 1.6;
  min-height: 100svh;
  display: grid;
  place-items: center;
  padding: 2rem 1rem;
}

/* ===== Skip link ===== */
.skip-link {
  position: absolute;
  top: -100%;
  left: 1rem;
  background: var(--accent);
  color: #fff;
  padding: 0.5rem 1rem;
  border-radius: 0 0 var(--radius) var(--radius);
  font-weight: 600;
  text-decoration: none;
  z-index: 9999;
  transition: top var(--transition);
}
.skip-link:focus {
  top: 0;
}

/* ===== Form section ===== */
.form-section {
  background: var(--bg-surface);
  border: 1px solid var(--border-idle);
  border-radius: 16px;
  padding: clamp(1.5rem, 5vw, 2.5rem);
  width: 100%;
  max-width: 480px;
  box-shadow: 0 8px 32px rgba(0, 0, 0, 0.5);
}

h1 {
  font-size: clamp(1.4rem, 4vw, 1.75rem);
  font-weight: 700;
  color: var(--text-primary);
  letter-spacing: -0.01em;
}

.form-intro {
  color: var(--text-secondary);
  margin-top: 0.4rem;
  font-size: 0.9375rem;
}

.required-note {
  font-size: 0.8125rem;
  color: var(--text-secondary);
  margin-top: 1.25rem;
}

.required-note .required-star,
.required-star {
  color: var(--error);
  font-weight: 700;
  margin-right: 0.15em;
}

/* ===== Form layout ===== */
form {
  margin-top: 1.5rem;
  display: flex;
  flex-direction: column;
  gap: 1.25rem;
}

/* ===== Form field ===== */
.form-field {
  display: flex;
  flex-direction: column;
  gap: 0.375rem;
}

label {
  font-size: 0.9375rem;
  font-weight: 500;
  color: var(--text-label);
}

input {
  background: var(--bg-input);
  border: 1.5px solid var(--border-idle);
  border-radius: var(--radius);
  color: var(--text-primary);
  font-size: 1rem;
  padding: 0.625rem 0.875rem;
  transition: border-color var(--transition), box-shadow var(--transition);
  outline: none;
  width: 100%;
}

input::placeholder {
  color: var(--text-secondary);
  opacity: 0.7;
}

input:hover:not(:focus) {
  border-color: #4a4f72;
}

input:focus {
  border-color: var(--border-focus);
  box-shadow: 0 0 0 3px rgba(108, 140, 255, 0.25);
}

input[aria-invalid="true"] {
  border-color: var(--border-error);
}

input[aria-invalid="true"]:focus {
  box-shadow: 0 0 0 3px rgba(240, 106, 106, 0.25);
}

/* ===== Help & error text ===== */
.field-help {
  font-size: 0.8125rem;
  color: var(--text-secondary);
}

.field-error {
  font-size: 0.8125rem;
  color: var(--error);
  font-weight: 500;
  min-height: 1.2em; /* reserve space to prevent layout shift */
}

.field-error:empty {
  min-height: 0;
}

/* ===== Live regions ===== */
#form-error-summary {
  border-radius: var(--radius);
  font-size: 0.9rem;
  font-weight: 500;
}

#form-error-summary:not(:empty) {
  background: rgba(240, 106, 106, 0.12);
  border: 1px solid var(--border-error);
  color: #f99;
  padding: 0.75rem 1rem;
  margin-top: 1rem;
}

#form-success:not(:empty) {
  background: rgba(94, 207, 138, 0.12);
  border: 1px solid var(--success);
  color: var(--success);
  padding: 0.75rem 1rem;
  border-radius: var(--radius);
  font-size: 0.9rem;
  font-weight: 500;
  margin-top: 1rem;
}

/* ===== Submit button ===== */
button[type="submit"] {
  align-self: flex-start;
  background: var(--accent);
  border: none;
  border-radius: var(--radius);
  color: #fff;
  cursor: pointer;
  font-size: 1rem;
  font-weight: 600;
  padding: 0.7rem 1.75rem;
  transition: background var(--transition), box-shadow var(--transition);
  min-width: 10rem;
  margin-top: 0.25rem;
}

button[type="submit"]:hover {
  background: var(--accent-hover);
}

button[type="submit"]:focus-visible {
  outline: 3px solid var(--border-focus);
  outline-offset: 3px;
}

button[type="submit"]:active {
  background: #5570e0;
}

/* ===== Forced colors (high contrast) ===== */
@media (forced-colors: active) {
  input {
    border: 2px solid ButtonText;
    background: Field;
    color: FieldText;
  }
  input:focus {
    outline: 3px solid Highlight;
  }
  button[type="submit"] {
    border: 2px solid ButtonText;
    background: ButtonFace;
    color: ButtonText;
    forced-color-adjust: none;
  }
}

/* ===== Reduced motion ===== */
@media (prefers-reduced-motion: reduce) {
  *, *::before, *::after {
    transition-duration: 0.01ms !important;
  }
}

/* ===== Narrow-viewport reflow (320 px) ===== */
@media (max-width: 380px) {
  .form-section {
    border-radius: 0;
    border-left: none;
    border-right: none;
  }
  button[type="submit"] {
    width: 100%;
    align-self: stretch;
  }
}
