   const form = document.getElementById('contact-form');
   const errorSummary = document.getElementById('form-error-summary');
   const successRegion = document.getElementById('form-success');

   // Phone format: optional +country code, area code, 7-digit number
   const PHONE_RE = /^\+?[\d\s\-().]{7,20}$/;

   // Field descriptors -------------------------------------------------------
   const fields = [
     {
       id: 'full-name',
       errorId: 'full-name-error',
       label: 'Full name',
       validate(val) {
         if (!val.trim()) return 'Error: Full name is required.';
         return null;
       },
     },
     {
       id: 'email',
       errorId: 'email-error',
       label: 'Email address',
       validate(val) {
         if (!val.trim()) return 'Error: Email address is required.';
         if (!/^[^\s@]+@[^\s@]+\.[^\s@]+$/.test(val.trim()))
           return 'Error: Enter a valid email address like name@example.com.';
         return null;
       },
     },
     {
       id: 'phone',
       errorId: 'phone-error',
       label: 'Phone number',
       validate(val) {
         if (val.trim() && !PHONE_RE.test(val.trim()))
           return 'Error: Enter a valid phone number, e.g. +1 (555) 000-0000.';
         return null;
       },
     },
   ];

   // Helpers -----------------------------------------------------------------

   function getInput(field) {
     return document.getElementById(field.id);
   }

   function getErrorEl(field) {
     return document.getElementById(field.errorId);
   }

   /** Mark a field valid: clear error text, remove invalid state. */
   function clearError(field) {
     const input = getInput(field);
     const errorEl = getErrorEl(field);
     errorEl.textContent = '';
     input.removeAttribute('aria-invalid');
   }

   /** Mark a field invalid: set error text, set aria-invalid. */
   function setError(field, message) {
     const input = getInput(field);
     const errorEl = getErrorEl(field);
     errorEl.textContent = message;
     input.setAttribute('aria-invalid', 'true');
   }

   /** Validate a single field and update its UI. Returns error string or null. */
   function validateField(field) {
     const val = getInput(field).value;
     const error = field.validate(val);
     if (error) {
       setError(field, error);
     } else {
       clearError(field);
     }
     return error;
   }

   // Inline validation on blur (only after first submit attempt) -------------
   let submitted = false;

   fields.forEach((field) => {
     getInput(field).addEventListener('blur', () => {
       if (submitted) validateField(field);
     });
     getInput(field).addEventListener('input', () => {
       if (submitted) validateField(field);
     });
   });

   // Submit ------------------------------------------------------------------

   form.addEventListener('submit', (e) => {
     e.preventDefault();
     submitted = true;

     // Clear previous summary and success
     errorSummary.textContent = '';
     successRegion.textContent = '';

     const errors = fields.map(validateField).filter(Boolean);

     if (errors.length) {
       // Announce error count; focus first invalid input
       errorSummary.textContent =
